WITH flattened AS (SELECT id, service, log_ts, latency_ms, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, attr_value) SELECT id, service, latency_ms, CASE WHEN service RLIKE '^(checkout|auth)$' THEN 'CORE' WHEN service RLIKE '^(billing|search)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS service_zone FROM flattened ORDER BY service_zone NULLS FIRST, latency_ms
